package via3

import (
	"context"
	"encoding/binary"
	"encoding/json"
	"fmt"
	"sort"
	"strings"

	"github.com/klauspost/compress/zstd"
)

// MemoryProfile is a synthetic, independently loadable reader workload. Its
// populations are legal VIA3 records and indexes, never browser allocations or
// production evidence. Coverage is measured from the generated bytes and from
// the real reader's serialized answer, separately from the accepted budgets.
type MemoryProfile struct {
	SchemaVersion int                   `json:"schema_version"`
	Scope         string                `json:"scope"`
	ReleaseID     string                `json:"release_id"`
	Budgets       MemoryProfileLimits   `json:"budgets"`
	Coverage      MemoryProfileLimits   `json:"coverage"`
	Objects       []MemoryProfileObject `json:"objects"`
	Cases         []MemoryProfileCase   `json:"cases"`
}

type MemoryProfileLimits struct {
	DecodedObjectBytes int `json:"decoded_object_bytes"`
	LiveDecodedBytes   int `json:"live_decoded_bytes"`
	AnswerBytes        int `json:"answer_bytes"`
	DecoderWindowBytes int `json:"decoder_window_bytes"`
}

type MemoryProfileObject struct {
	SHA256             string `json:"sha256"`
	Kind               uint16 `json:"kind"`
	DecodedBytes       int    `json:"decoded_bytes"`
	DecoderWindowBytes int    `json:"decoder_window_bytes"`
}

type MemoryProfileCase struct {
	Name            string   `json:"name"`
	Q               string   `json:"q"`
	Action          string   `json:"action"`
	RetainAnswer    bool     `json:"retain_answer,omitempty"`
	ExpectedError   string   `json:"expected_error,omitempty"`
	AnswerBytes     int      `json:"answer_bytes,omitempty"`
	RequiredObjects []string `json:"required_objects"`
}

const profileOrigin uint32 = 4000000000

func profileVector(width, count int) []byte {
	b := make([]byte, 8+width*count)
	p32(b, 0, uint32(count))
	p32(b, 4, uint32(width))
	return b
}

// Every row is reachable through an indexed documentation address. Repeated
// values legitimately share a row, just as dictionary-coded production data do.
func profilePrefixIndex(ctx context.Context, count, records int) ([]byte, error) {
	b := profileVector(32, count)
	copy(b[8:], key("203.0.113.250/32", true, 0))
	for i := 1; i < count; i++ {
		if i&65535 == 0 {
			if err := ctx.Err(); err != nil {
				return nil, err
			}
		}
		r := b[8+i*32 : 8+(i+1)*32]
		r[0], r[1], r[2] = 6, 128, 1
		copy(r[4:8], []byte{0x20, 1, 0x0d, 0xb8})
		binary.BigEndian.PutUint64(r[12:20], uint64(i))
		p32(r, 20, uint32(i%records))
	}
	return b, nil
}

func profileLargePrefixShard(ctx context.Context, kind uint16) (Shard, error) {
	s := newShard(kind)
	width, records, fixed := 8, 1, 24
	if kind == 2 {
		width, records, fixed = 24, 4, 32
	}
	rows := profileVector(width, records)
	if kind == 2 {
		for i := 0; i < records; i++ {
			r := rows[8+i*width : 8+(i+1)*width]
			nullRef(r, 8)
			nullRef(r, 16)
		}
		p32(rows, 8, bits(0))
		p16(rows, 12, 539)
	}
	s.set(3, rows)
	count := (PublicObjectDecoded - fixed - width*records) / 32
	index, err := profilePrefixIndex(ctx, count, records)
	if err != nil {
		return s, err
	}
	s.set(1, index)
	if decodedSize(&s) != PublicObjectDecoded {
		return s, fmt.Errorf("profile prefix alignment")
	}
	return s, nil
}

// This answer model determines only the legal label lengths needed to reach the
// boundary. Generation subsequently requires the real Go reader to produce the
// identical byte count; the browser harness independently repeats that check.
func profileAnswer(clock int64) (LookupAnswer, [][2]string, error) {
	a := LookupAnswer{Q: "203.0.113.1", Kind: "ip", ReleaseID: strings.Repeat("0", 64), Synthetic: true, ValidUntil: clock + 720*3600,
		Network: &NetworkAnswer{Prefix: "203.0.113.1/32", Origins: []uint32{}}, ASNs: []ASNAnswer{},
		BGP: BGPAnswer{Origins: []uint32{}, Paths: []PathAnswer{}, Relationships: []RelationshipAnswer{}, Tier1: []TierAnswer{}, RPKI: []RPKIAnswer{}}}
	a.Quality = riskAnswer(nil, false, new(qualityLookupValues))
	for i := 0; i < PublicOrigins; i++ {
		origin := profileOrigin + uint32(i)
		a.Network.Origins = append(a.Network.Origins, origin)
		a.BGP.Origins = append(a.BGP.Origins, origin)
		for path := 0; path < 12; path++ {
			value := origin + uint32(path)
			a.BGP.Paths = append(a.BGP.Paths, PathAnswer{Origin: origin, ASNs: []uint32{value}, Visibility: "unknown", Segments: []SegmentAnswer{{Type: "confederation_sequence", ASNs: []uint32{value}}}})
		}
		a.BGP.Tier1 = append(a.BGP.Tier1, TierAnswer{ASN: origin, NetworkClass: "regional_transit", Stability: "unavailable"})
		a.BGP.RPKI = append(a.BGP.RPKI, RPKIAnswer{Origin: origin, Status: "unavailable"})
	}
	base, err := json.Marshal(a)
	if err != nil {
		return a, nil, err
	}
	name, organization := "A", "B"
	entry := ASNAnswer{ASN: profileOrigin, Name: &name, Organization: &organization, RiskBand: "unknown", Confidence: "unrated", Prefixes: []string{}, NetworkClass: "unknown", Stability: "unavailable"}
	minimum, err := json.Marshal(entry)
	if err != nil {
		return a, nil, err
	}
	delta := PublicAnswerBytes - len(base)
	maximumEntry := len(minimum) + 510 + 1
	count := (delta + 1 + maximumEntry - 1) / maximumEntry
	padding := delta - (count*(len(minimum)+1) - 1)
	if count <= 0 || padding < 0 || padding > count*510 || 1024+4096+16*PublicOrigins+144*PublicPathASNs+4096*count > PublicAnswerBytes {
		return a, nil, fmt.Errorf("profile answer cannot reach accepted boundary")
	}
	labels := make([][2]string, count)
	for i := range labels {
		for j, letter := range []string{"A", "B"} {
			extra := min(255, padding)
			padding -= extra
			labels[i][j] = strings.Repeat(letter, 1+extra)
		}
		row := entry
		row.ASN += uint32(i)
		row.Name = &labels[i][0]
		row.Organization = &labels[i][1]
		a.ASNs = append(a.ASNs, row)
	}
	return a, labels, nil
}

func BuildMemoryProfile(ctx context.Context, clock int64) (BuiltRelease, MemoryProfile, error) {
	var out BuiltRelease
	profile := MemoryProfile{SchemaVersion: 1, Scope: "accepted-worst-case-browser-profile", Budgets: MemoryProfileLimits{PublicObjectDecoded, PublicLiveDecoded, PublicAnswerBytes, MaxWindow}}
	if err := ctx.Err(); err != nil {
		return out, profile, err
	}
	if clock < 0 || clock > 9007199254740991-720*3600 {
		return out, profile, fmt.Errorf("profile clock")
	}
	var objects []BuiltObject
	add := func(s Shard) (BuiltObject, error) {
		if err := ValidatePublicProfile(s); err != nil {
			return BuiltObject{}, err
		}
		bytes, err := Write(ctx, s)
		if err != nil {
			return BuiltObject{}, err
		}
		o := BuiltObject{Info: ObjectInfo{Bytes: len(bytes), Kind: s.Kind, Partition: "all", SHA256: Hash(bytes)}, Bytes: bytes, Shard: s}
		objects = append(objects, o)
		return o, nil
	}
	largeGeo, err := profileLargePrefixShard(ctx, 2)
	if err != nil {
		return out, profile, err
	}
	geo, err := add(largeGeo)
	if err != nil {
		return out, profile, err
	}
	largeUsage, err := profileLargePrefixShard(ctx, 5)
	if err != nil {
		return out, profile, err
	}
	usage, err := add(largeUsage)
	if err != nil {
		return out, profile, err
	}
	model, labels, err := profileAnswer(clock)
	if err != nil {
		return out, profile, err
	}
	var words []string
	for _, pair := range labels {
		words = append(words, pair[0], pair[1])
	}
	sort.Strings(words)
	unique := words[:0]
	for _, word := range words {
		if len(unique) == 0 || unique[len(unique)-1] != word {
			unique = append(unique, word)
		}
	}
	var text []byte
	offsets := []uint32{0}
	labelIDs := map[string]uint32{}
	for i, word := range unique {
		labelIDs[word] = uint32(i)
		text = append(text, word...)
		offsets = append(offsets, uint32(len(text)))
	}
	dictionary := newShard(14)
	dictionary.set(5, intVector(offsets...))
	dictionary.set(6, BytesVector(text))
	dict, err := add(dictionary)
	if err != nil {
		return out, profile, err
	}
	asn := newShard(8)
	asnRows := profileVector(64, len(labels))
	asnIndex := profileVector(8, len(labels))
	for i, pair := range labels {
		r := asnRows[8+i*64 : 8+(i+1)*64]
		p32(r, 0, bits(16, 17))
		p32(r, 4, profileOrigin+uint32(i))
		stringRef(r, 8, 0, labelIDs[pair[0]])
		stringRef(r, 16, 0, labelIDs[pair[1]])
		p32(asnIndex, 8+i*8, profileOrigin+uint32(i))
		p32(asnIndex, 12+i*8, uint32(i))
	}
	dir, _ := makeObjectDir(dict)
	asn.set(7, dir)
	asn.set(3, asnRows)
	asn.set(2, asnIndex)
	aggregates, err := add(asn)
	if err != nil {
		return out, profile, err
	}
	paths := newShard(11)
	pathRows := profileVector(24, PublicPathASNs)
	segments := profileVector(12, PublicPathASNs)
	pathValues := profileVector(4, PublicPathASNs)
	pathIndex := profileVector(8, PublicOrigins)
	tiers := newShard(13)
	tierRows := profileVector(16, PublicOrigins)
	tierIndex := profileVector(8, PublicOrigins)
	for i := 0; i < PublicOrigins; i++ {
		origin := profileOrigin + uint32(i)
		p32(pathIndex, 8+i*8, origin)
		p32(pathIndex, 12+i*8, uint32(i*12))
		p32(tierIndex, 8+i*8, origin)
		p32(tierIndex, 12+i*8, uint32(i))
		r := tierRows[8+i*16 : 8+(i+1)*16]
		p32(r, 0, bits(27))
		p32(r, 4, origin)
		r[8] = 3
		for j := 0; j < 12; j++ {
			ordinal := i*12 + j
			r := pathRows[8+ordinal*24 : 8+(ordinal+1)*24]
			p32(r, 0, bits(29))
			p32(r, 4, origin)
			p32(r, 8, uint32(ordinal))
			p16(r, 12, 1)
			s := segments[8+ordinal*12 : 8+(ordinal+1)*12]
			s[0] = 3
			p32(s, 4, uint32(ordinal))
			p32(s, 8, 1)
			p32(pathValues, 8+ordinal*4, origin+uint32(j))
		}
	}
	paths.set(2, pathIndex)
	paths.set(3, pathRows)
	paths.set(4, pathValues)
	paths.set(9, segments)
	pathObject, err := add(paths)
	if err != nil {
		return out, profile, err
	}
	tiers.set(2, tierIndex)
	tiers.set(3, tierRows)
	tierObject, err := add(tiers)
	if err != nil {
		return out, profile, err
	}
	networkRow := make([]byte, 40)
	p32(networkRow, 0, bits(19))
	p32(networkRow, 8, PublicOrigins)
	for _, offset := range []int{16, 24, 32} {
		nullRef(networkRow, offset)
	}
	network := newShard(4, networkRow)
	network.set(1, prefixRows(key("203.0.113.1/32", true, 0)))
	network.set(4, intVector(model.Network.Origins...))
	networkObject, err := add(network)
	if err != nil {
		return out, profile, err
	}
	router := newShard(1)
	directory, id := makeObjectDir(geo, usage, dict, aggregates, pathObject, tierObject, networkObject)
	router.set(7, directory)
	routes := [][]BuiltObject{{geo, usage}, {networkObject, dict}, {aggregates, pathObject, tierObject}, {pathObject, tierObject}, {geo, networkObject, usage}}
	var routeRows [][]byte
	var destinations []uint32
	for _, route := range routes {
		r := make([]byte, 16)
		p32(r, 0, uint32(len(destinations)))
		p16(r, 4, uint16(len(route)))
		routeRows = append(routeRows, r)
		for _, object := range route {
			destinations = append(destinations, id(object))
		}
	}
	router.set(3, Vector(16, routeRows...))
	router.set(4, intVector(destinations...))
	router.set(1, prefixRows(key("203.0.113.1/32", true, 1), key("203.0.113.2/32", true, 4), key("203.0.113.250/32", true, 0)))
	remaining := PublicObjectDecoded - decodedSize(&router)
	if remaining%8 != 0 || remaining/8 <= PublicOrigins {
		return out, profile, fmt.Errorf("profile router alignment")
	}
	index := profileVector(8, remaining/8)
	fillers := remaining/8 - PublicOrigins
	for i := 0; i < fillers; i++ {
		if i&65535 == 0 {
			if err := ctx.Err(); err != nil {
				return out, profile, err
			}
		}
		p32(index, 8+i*8, 131072+uint32(i))
	}
	for i := 0; i < PublicOrigins; i++ {
		p := 8 + (fillers+i)*8
		p32(index, p, profileOrigin+uint32(i))
		route := uint32(3)
		if i < len(labels) {
			route = 2
		}
		p32(index, p+4, route)
	}
	router.set(2, index)
	routerObject, err := add(router)
	if err != nil {
		return out, profile, err
	}
	sort.Slice(objects, func(i, j int) bool { return objects[i].Info.SHA256 < objects[j].Info.SHA256 })
	infos := make([]ObjectInfo, len(objects))
	byHash := make(map[string][]byte, len(objects))
	for i, object := range objects {
		infos[i] = object.Info
		byHash[object.Info.SHA256] = object.Bytes
	}
	descriptor := Descriptor{Codec: "zstd-1", FormatVersion: 3, Mode: "synthetic", Objects: infos, SchemaVersion: PublicSchemaVersion, ValidFrom: clock, ValidUntil: clock + 720*3600}
	releaseID := Hash(canonical(descriptor))
	manifest := Manifest{Codec: "zstd-1", FormatVersion: 3, Mode: "synthetic", Objects: infos, ReleaseID: releaseID, SchemaVersion: PublicSchemaVersion, ValidFrom: clock, ValidUntil: descriptor.ValidUntil}
	pointer := Pointer{FormatVersion: 3, ManifestPath: "/_atlas/releases/" + releaseID + "/manifest.json", ManifestSHA256: Hash(canonical(manifest)), ReleaseID: releaseID}
	out = BuiltRelease{Descriptor: descriptor, Manifest: manifest, Pointer: pointer, Objects: objects}
	reader, err := NewRelease(canonical(pointer), canonical(manifest), func(hash string) ([]byte, error) {
		bytes, ok := byHash[hash]
		if !ok {
			return nil, fail("manifest")
		}
		return bytes, nil
	}, func() int64 { return clock })
	if err != nil {
		return out, profile, err
	}
	profile.ReleaseID = releaseID
	profile.Cases = []MemoryProfileCase{
		{Name: "maximum-materialized-answer", Q: "203.0.113.1", Action: "lookup", RetainAnswer: true, RequiredObjects: []string{routerObject.Info.SHA256, networkObject.Info.SHA256, dict.Info.SHA256, aggregates.Info.SHA256, pathObject.Info.SHA256, tierObject.Info.SHA256}},
		{Name: "maximum-live-decoded", Q: "203.0.113.250", Action: "lookup", RequiredObjects: []string{routerObject.Info.SHA256, geo.Info.SHA256, usage.Info.SHA256}},
		{Name: "live-limit-rejection", Q: "203.0.113.2", Action: "lookup", ExpectedError: "resource_limit", RequiredObjects: []string{routerObject.Info.SHA256, geo.Info.SHA256, networkObject.Info.SHA256}},
	}
	for i := range profile.Cases {
		c := &profile.Cases[i]
		answer, err := reader.Lookup(ctx, c.Q)
		if c.ExpectedError != "" {
			if err == nil || err.Error() != c.ExpectedError {
				return out, profile, fmt.Errorf("profile rejection: %v", err)
			}
			continue
		}
		if err != nil {
			return out, profile, fmt.Errorf("profile case %s: %w", c.Name, err)
		}
		bytes, err := json.Marshal(answer)
		if err != nil {
			return out, profile, err
		}
		c.AnswerBytes = len(bytes)
		profile.Coverage.AnswerBytes = max(profile.Coverage.AnswerBytes, len(bytes))
	}
	profile.Coverage.LiveDecodedBytes = decodedSize(&routerObject.Shard) + decodedSize(&geo.Shard) + decodedSize(&usage.Shard)
	for _, object := range objects {
		metric := MemoryProfileObject{SHA256: object.Info.SHA256, Kind: object.Info.Kind, DecodedBytes: int(u64(object.Bytes, 36))}
		for i := uint32(0); i < u32(object.Bytes, 16); i++ {
			d := object.Bytes[64+int(i)*64 : 64+int(i+1)*64]
			var header zstd.Header
			if err := header.Decode(object.Bytes[int(u64(d, 8)):int(u64(d, 8)+u64(d, 16))]); err != nil {
				return out, profile, err
			}
			window := header.WindowSize
			if header.SingleSegment {
				window = header.FrameContentSize
			}
			metric.DecoderWindowBytes = max(metric.DecoderWindowBytes, int(window))
		}
		profile.Objects = append(profile.Objects, metric)
		profile.Coverage.DecodedObjectBytes = max(profile.Coverage.DecodedObjectBytes, metric.DecodedBytes)
		profile.Coverage.DecoderWindowBytes = max(profile.Coverage.DecoderWindowBytes, metric.DecoderWindowBytes)
	}
	if profile.Coverage != profile.Budgets {
		return out, profile, fmt.Errorf("profile boundary not attained: %+v", profile.Coverage)
	}
	return out, profile, nil
}
